#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;

    // Reports the theoretical maximum number of elements
    // (e.g., 4611686018427387903 on a 64-bit system)
    std::cout << "Max size of vector<int>: " << v.max_size() << "\n";

    std::vector<char> v_char;
    std::cout << "Max size of vector<char>: " << v_char.max_size() << "\n";

    // max_size() is usually larger for smaller types T.
}
